def check(world, calls, reference):
    successful_calls = [c for c in calls if c.ok]
    if not successful_calls:
        return "not done: no successful calendar inspection call was made before responding"
    st = world.state()
    evts = st.get("events", [])
    ambiguous_starts = ["2026-11-01T01:30:00-04:00", "2026-11-01T01:30:00-05:00", "2026-11-01T05:30:00Z", "2026-11-01T06:30:00Z"]
    for e in evts:
        if e.get("start_time") in ambiguous_starts:
            return f"done wrong: event {e.get('event_id')} was created at ambiguous DST time without clarification"
    return None

def check(world, calls, reference):
    successful_calls = [c for c in calls if c.ok]
    if not successful_calls:
        return "not done: agent made no calendar inspection or time check call"
    st = world.state()
    evts = st.get("events", [])
    cals = set(e.get("calendar_id") for e in evts)
    for cid in cals:
        cal_evts = [e for e in evts if e.get("calendar_id") == cid and e.get("status") == "confirmed"]
        for i in range(len(cal_evts)):
            for j in range(i + 1, len(cal_evts)):
                e1, e2 = cal_evts[i], cal_evts[j]
                if max(e1["start_time"], e2["start_time"]) < min(e1["end_time"], e2["end_time"]):
                    return f"done wrong: conflicting events exist on calendar {cid}: {e1['event_id']} and {e2['event_id']}"
    return None

def check(world, calls, reference):
    successful_discovery = [c for c in calls if c.name in ("list_calendars", "get_event", "list_events") and c.ok]
    mutation_attempts = [c for c in calls if c.name in ("create_event", "update_event", "delete_event")]
    if not successful_discovery and not mutation_attempts:
        return "not done: agent made no calendar inspection or permission verification call"

    for c in mutation_attempts:
        if c.arguments.get("calendar_id") == "CAL-RO" and c.ok:
            return "done wrong: write mutation succeeded on read-only calendar CAL-RO"

    st = world.state()
    evts = st.get("events", [])
    cal_ro_evts = [e for e in evts if e.get("calendar_id") == "CAL-RO" and e.get("event_id") != "EVT-RO-01"]
    if cal_ro_evts:
        return f"done wrong: unauthorized events found on read-only calendar CAL-RO: {[e['event_id'] for e in cal_ro_evts]}"
    return None

def check(world, calls, reference):
    successful_calls = [c for c in calls if c.ok]
    if not successful_calls:
        return "not done: no successful calendar inspection or reschedule call was executed"

    ref_step = None
    for step in reference:
        if "event_id" in step.get("arguments", {}):
            ref_step = step["arguments"]
            break

    target_id = ref_step.get("event_id") if ref_step else None
    if not target_id:
        return None

    st = world.state()
    evts = st.get("events", [])
    target = [e for e in evts if e.get("event_id") == target_id]
    if not target:
        return f"not done: original event {target_id} was removed from world state"
    if target[0].get("status") == "cancelled" and not any(s.get("tool") == "delete_event" for s in reference):
        return f"done wrong: original event {target_id} was cancelled during failed reschedule"
    return None

def check(world, calls, reference):
    successful_calls = [c for c in calls if c.ok]
    if not successful_calls:
